package main
import("fmt";"time";"sync")
func main(){const n=__MESSAGES__;const producers=4;const consumers=1;setup:=time.Now();ch:=make(chan int,64);results:=make(chan int,consumers);jobs:=make([]func(),0,producers+consumers);for id:=0;id<producers;id++{id:=id;jobs=append(jobs,func(){for i:=0;i<n/producers;i++{ch<-id*(n/producers)+i}})};for id:=0;id<consumers;id++{jobs=append(jobs,func(){sum:=0;last:=make([]int,producers);for i:=range last{last[i]=-1};for seen:=0;seen<n/consumers;seen++{v:=<-ch;id:=v/(n/producers);seq:=v%(n/producers);if seq<=last[id]{panic("per-producer FIFO mismatch")};last[id]=seq;sum+=v};results<-sum})};t0:=time.Now();var wg sync.WaitGroup;wg.Add(len(jobs));for _,job:=range jobs{go func(job func()){defer wg.Done();job()}(job)};wg.Wait();sum:=0;for id:=0;id<consumers;id++{sum+=<-results};t1:=time.Now();fmt.Println(sum);fmt.Printf("setup_ns=%d\nbench_ns=%d\n",t0.Sub(setup).Nanoseconds(),t1.Sub(t0).Nanoseconds())}
